#!/usr/bin/env python3
from pathlib import Path
from datetime import datetime, timezone
import hashlib,json
ROOT=Path('/home/ubuntu/CHAOS'); LEDGER=ROOT/'research_ledger/RESEARCH_LEDGER_V1.jsonl'
def h(rel): return hashlib.sha256((ROOT/rel).read_bytes()).hexdigest()
def add(ledger_id,record_type,status,contract_ref,refs,notes):
 rec={'contract_ref':contract_ref,'created_at_utc':datetime.now(timezone.utc).isoformat(),'input_hashes':{r:h(r) for r in refs if (ROOT/r).exists()},'ledger_id':ledger_id,'notes':notes,'output_refs':refs,'record_type':record_type,'status':status}
 rec['record_hash']=hashlib.sha256(json.dumps(rec,sort_keys=True,ensure_ascii=False).encode()).hexdigest(); return rec
records=[
 add('BROWSER_DEEP_RESEARCH_ROUND_01','research_round','active','campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH/BROWSER_DEEP_RESEARCH_ROUND_CONTRACT_V1.json',['campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH/BROWSER_DEEP_RESEARCH_ROUND_CONTRACT_V1.json','campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH/OFFICIAL_SOURCE_RESEARCH_INDEX_V1.json','campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH/BROWSER_DEEP_RESEARCH_PROVENANCE_V1.json'],'official browser deep research builds above frozen baseline; raw immutable; no arbitrary rerun'),
 add('OECD_PMR_ARCHIVE_ACQUISITION_V1','source_extract','ready','campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH/OECD_PMR_ACQUISITION_SUMMARY_V1.json',['campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH/OECD_PMR_ACQUISITION_SUMMARY_V1.json','campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH/OECD_PMR_RAW_PROFILE_V1.json','campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH/OECD_PMR_DOMAIN_STATES_SOURCE_WAVES_V1.jsonl'],'official OECD PMR archive acquired via verified SDMX fallback; 4,134 rows; 47 economies; four source-defined waves; raw excluded from Git'),
 add('OECD_PMR_TRANSITION_EVIDENCE_V1','transition_evidence','not_testable','campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH/OECD_PMR_TRANSITION_EVIDENCE_V1.jsonl',['campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH/OECD_PMR_TRANSITION_EVIDENCE_V1.jsonl','experiments/macro_plus_eia_energy/CONTROLLED_PATTERN_REGISTRY_V1.jsonl'],'four waves/archive vintage and no dated policy shock do not support robust OOS/null transition test; no positive weight'),
 add('WGI_PMR_DESCRIPTIVE_COMPARISON_V1','comparison','descriptive_only','campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH/WGI_PMR_SOURCE_COMPARISON_V1.json',['campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH/WGI_PMR_SOURCE_COMPARISON_V1.json','campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH/WGI_PMR_SOURCE_COMPARISON_REPORT_AR.md'],'exact entity-year descriptive comparison only; Pearson Regulatory Quality vs PMR reported negative; no edge or causal claim'),
 add('IMF_ITG_IMTS_CATALOG_FOLLOWUP_V1','source_research','download_pending','campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH/TRADE_OFFICIAL_SOURCE_FINDINGS_ROUND9_AR.md',['campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH/TRADE_OFFICIAL_SOURCE_FINDINGS_ROUND7_AR.md','campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH/TRADE_OFFICIAL_SOURCE_FINDINGS_ROUND8_AR.md','campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH/TRADE_OFFICIAL_SOURCE_FINDINGS_ROUND9_AR.md','campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH/IMF_ITG_IMTS_LINK_ANALYSIS_V1.json'],'IMF ITG and current IMTS successor to DOTS confirmed in official catalog; UI/HTML follow-up did not expose a verified download URL; no IMF file or states claimed'),
 add('CAMPAIGN_SUPERVISOR_QA_BROWSER_ROUND_01','qa','pass','campaigns/CAMPAIGN_SHARED_GATE_V1/CAMPAIGN_QA_MANIFEST_V1.json',['campaigns/CAMPAIGN_SHARED_GATE_V1/CAMPAIGN_QA_MANIFEST_V1.json','campaigns/CAMPAIGN_SHARED_GATE_V1/FINAL_SUPERVISOR_ELIGIBILITY_GATE_V1.json','experiments/macro_plus_eia_energy/evidence_graph_v1/EVIDENCE_GRAPH_SUMMARY.json'],'47 graph nodes and 50 edges; 2 admitted supported_predictive historical records; 23 quarantined; 0 runtime-eligible; 0 causal claims; raw/frequency gates pass')
]
old=LEDGER.read_text(encoding='utf8').splitlines(); ids={json.loads(x).get('ledger_id') for x in old if x.strip()}
with LEDGER.open('a',encoding='utf8') as f:
 for r in records:
  if r['ledger_id'] not in ids: f.write(json.dumps(r,ensure_ascii=False,sort_keys=True)+'\n')
print(json.dumps({'appended':[r['ledger_id'] for r in records if r['ledger_id'] not in ids], 'ledger_lines_before':len(old), 'ledger_lines_after':len(old)+sum(r['ledger_id'] not in ids for r in records)},ensure_ascii=False,indent=2))
